'use strict';


// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrnanmsumabs2 = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmsumabs2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a positive integer', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		-5.0,
		0.0,
		3.14,
		true,
		null,
		void 0,
		NaN,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			incrnanmsumabs2( value );
		};
	}
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.equal( typeof incrnanmsumabs2( 3 ), 'function', 'returns a function' );
	t.end();
});

tape( 'the accumulator function computes a moving sum of squared absolute values incrementally', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var N;
	var i;

	data = [ 2.0, -3.0, 2.0, -4.0, 3.0, -4.0 ];
	N = data.length;

	acc = incrnanmsumabs2( 3 );

	actual = [];
	for ( i = 0; i < N; i++ ) {
		actual.push( acc( data[ i ] ) );
	}
	expected = [ 4.0, 13.0, 17.0, 29.0, 29.0, 41.0 ];

	t.deepEqual( actual, expected, 'returns expected incremental results' );
	t.end();
});

tape( 'the accumulator function correctly handles NaN values by ignoring them', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var N;
	var i;

	data = [ 2.0, NaN, -3.0, NaN, 2.0, -4.0, 3.0, NaN, -4.0 ];
	N = data.length;

	acc = incrnanmsumabs2( 3 );

	actual = [];
	for ( i = 0; i < N; i++ ) {
		actual.push( acc( data[ i ] ) );
	}
	expected = [ 4.0, 4.0, 13.0, 13.0, 17.0, 29.0, 29.0, 29.0, 41.0 ];

	t.deepEqual( actual, expected, 'returns expected incremental results when handling NaN values' );
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current sum', function test( t ) {
	var data;
	var acc;
	var i;

	data = [ 2.0, -3.0, -5.0 ];
	acc = incrnanmsumabs2( 2 );
	for ( i = 0; i < data.length; i++ ) {
		acc( data[ i ] );
	}
	t.equal( acc(), 34.0, 'returns expected value' );
	t.end();
});

tape( 'if data has yet to be provided, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanmsumabs2( 3 );
	t.equal( acc(), null, 'returns null' );
	t.end();
});

tape( 'if only provided `NaN` values, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanmsumabs2( 3 );
	acc( NaN );
	acc( NaN );
	acc( NaN );
	t.equal( acc(), null, 'returns null' );
	t.end();
});

tape( 'the accumulator function does not include `NaN` values in the window size count', function test( t ) {
	var data;
	var acc;
	var i;

	data = [ 2.0, -3.0, NaN, 5.0 ];
	acc = incrnanmsumabs2( 3 );
	for ( i = 0; i < data.length; i++ ) {
		acc( data[ i ] );
	}
	t.equal( acc(), 38.0, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function can handle a mixture of `NaN` and non-`NaN` values', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var N;
	var i;

	data = [
		NaN,  // null (no values)
		3.14, // 9.8596
		NaN,  // still 9.8596
		3.14, // 19.7192
		NaN,  // still 19.7192
		NaN,  // still 19.7192
		3.14, // 29.5788
		3.14, // 29.5788 (3.14, 3.14, 3.14)
		NaN,  // 29.5788
		3.14  // 29.5788 (3.14, 3.14, 3.14)
	];

	expected = [
		null,
		9.8596,
		9.8596,
		19.7192,
		19.7192,
		19.7192,
		29.5788,
		29.5788,
		29.5788,
		29.5788
	];

	acc = incrnanmsumabs2( 3 );

	actual = [];
	for ( i = 0; i < data.length; i++ ) {
		actual.push( acc( data[ i ] ) );
	}

	for ( i = 0; i < expected.length; i++ ) {
		if ( expected[i] === null ) {
			t.equal( actual[i], null, 'returns expected value for index ' + i );
		} else {
			t.equal( actual[i], expected[i], 'returns expected value for index ' + i );
		}
	}

	t.end();
});
